  function stopLasso(){lassoActive=false;lassoPath=[];lassoFinished=false;document.body.classList.remove('pf36-selection-mode');$('pf36LassoDock').hidden=true;if(selectCtx)selectCtx.clearRect(0,0,selectCanvas.width,selectCanvas.height);$('pf36PointCount').textContent='0';$('pf36MaskStatus').textContent='待機'}
