  $('pf36MaskInside').addEventListener('click',()=>applyLasso(false));$('pf36MaskOutside').addEventListener('click',()=>applyLasso(true));$('pf36DockInside').addEventListener('click',()=>applyLasso(false));$('pf36DockOutside').addEventListener('click',()=>applyLasso(true));$('pf36DockCancel').addEventListener('click',stopLasso);

  // 04 · layer utilities and non-destructive filter copies.
  function refreshLayers(){const wrap=$('pf36LayerList');if(!wrap)return;wrap.innerHTML='';const active=API().getActiveLayer();for(const layer of [...API().getLayers()].reverse()){const row=document.createElement('div');row.className='pf36-layerrow';const thumb=document.createElement('canvas');thumb.width=68;thumb.height=52;thumb.getContext('2d').drawImage(layer.canvas,0,0,68,52);const name=document.createElement('span');name.textContent=layer.name+(layer.id===active?.id?' · 選択中':'');name.style.cursor='pointer';name.addEventListener('click',()=>{API().selectLayer(layer.id);refreshLayers()});const visibility=document.createElement('button');visibility.className='pf36-btn';visibility.textContent=layer.visible?'表示':'非表示';visibility.addEventListener('click',()=>{API().setLayerVisibility(layer.id,!layer.visible);refreshLayers()});row.append(thumb,name,visibility);wrap.appendChild(row)}}
  $('pf36NewLayer').addEventListener('click',()=>{API().addLayer('Studio Layer');refreshLayers()});$('pf36DuplicateLayer').addEventListener('click',()=>{API().duplicateLayer();refreshLayers()});$('pf36RefreshLayers').addEventListener('click',refreshLayers);
