  function drawNodePreview(){const c=$('pf36NodePreview');if(!c)return;const ctx=c.getContext('2d'),kind=$('pf36NodeType').value,a=$('pf36NodeColorA').value,b=$('pf36NodeColorB').value,scale=Number($('pf36NodeScale').value);const g=ctx.createLinearGradient(0,0,c.width,c.height);g.addColorStop(0,a);g.addColorStop(1,b);ctx.fillStyle=g;ctx.fillRect(0,0,c.width,c.height);const img=ctx.getImageData(0,0,c.width,c.height),d=img.data;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++){const i=(y*c.width+x)*4,t=kind==='radial'?Math.min(1,Math.hypot(x-c.width/2,y-c.height/2)/(Math.max(c.width,c.height)*.56)):kind==='stripes'?((Math.floor(x/scale)%2)?1:0):kind==='grid'?((x%scale<2||y%scale<2)?0:1):kind==='checker'?((Math.floor(x/scale)+Math.floor(y/scale))%2):((Math.sin(x/scale*1.8)+Math.sin(y/scale*1.5)+Math.sin((x+y)/scale))/6+.5);if(kind==='noise'){const v=Math.random()*.28-.14;d[i]=Math.max(0,Math.min(255,d[i]+v*255));d[i+1]=Math.max(0,Math.min(255,d[i+1]+v*255));d[i+2]=Math.max(0,Math.min(255,d[i+2]+v*255))}else{const v=Math.max(0,Math.min(1,t));d[i]=Math.round(d[i]*(1-v));d[i+1]=Math.round(d[i+1]*(1-v));d[i+2]=Math.round(d[i+2]*(1-v))}}ctx.putImageData(img,0,0)}
