  // 14 · storyboard storage.
  function getBoards(){try{return JSON.parse(localStorage.getItem(STORY_KEY)||'[]')}catch(_){return []}}
  function refreshBoards(){const wrap=$('pf36BoardList');wrap.innerHTML='';getBoards().forEach((b,i)=>{const item=document.createElement('article');item.className='pf36-board';const img=document.createElement('img');img.src=b.image;img.alt='ボードのサムネイル';const title=document.createElement('strong');title.textContent=b.title;const note=document.createElement('small');note.textContent=b.note||new Date(b.created).toLocaleString();const actions=document.createElement('div');actions.className='pf36-row';const add=document.createElement('button');add.className='pf36-btn';add.textContent='作品へ配置';add.addEventListener('click',()=>API().createLayerFromImage(b.image,'Storyboard · '+b.title).then(refreshLayers));const del=document.createElement('button');del.className='pf36-btn danger';del.textContent='削除';del.addEventListener('click',()=>{const all=getBoards();all.splice(i,1);localStorage.setItem(STORY_KEY,JSON.stringify(all));refreshBoards()});actions.append(add,del);item.append(img,title,note,actions);wrap.appendChild(item)})}
